<script setup>
import { ref } from 'vue';
import axios from 'axios';
import { Head, Link, useForm } from '@inertiajs/vue3';
import { ArrowLeft, Users, UserPlus, Search } from 'lucide-vue-next';
import WorkspaceShell from '@/Layouts/WorkspaceShell.vue';
import Button from '@/Components/UI/Button.vue';
import Input from '@/Components/UI/Input.vue';
import Modal from '@/Components/UI/Modal.vue';
import SimplePagination from '@/Components/UI/SimplePagination.vue';
const props = defineProps({ organization: Object, license: Object, assignments: Object, departments: Array });
const open = ref(false), mode = ref('members'), query = ref(''), results = ref([]), selected = ref([]), searching = ref(false), searchError = ref(''), searched = ref(false), releasing = ref(null);
const form = useForm({ user_ids: [], department_id: '', deadline: '' });
const removal = useForm({});
const search = async () => { if (query.value.trim().length < 2 || searching.value) return; searching.value = true; searched.value = false; searchError.value = ''; try { const { data } = await axios.get(`/organization/licenses/${props.license.id}/members`, { params: { search: query.value.trim() }, timeout: 20000 }); results.value = data.members; searched.value = true; } catch { searchError.value = 'Could not load learners. Check your connection and try again.'; } finally { searching.value = false; } };
const toggle = member => { const i = selected.value.findIndex(p => p.id === member.id); if (i < 0) selected.value.push(member); else selected.value.splice(i, 1); };
const assign = () => { form.user_ids = mode.value === 'members' ? selected.value.map(p => p.id) : []; if (mode.value === 'members') form.department_id = ''; form.post(`/organization/licenses/${props.license.id}/assign`, { preserveScroll: true, onSuccess: () => { open.value = false; form.reset(); selected.value = []; results.value = []; query.value = ''; } }); };
const release = () => removal.delete(`/organization/licenses/${props.license.id}/assignments/${releasing.value.id}`, { preserveScroll: true, onSuccess: () => { releasing.value = null; } });
</script>
<template>
    <Head :title="license.course?.title || 'Course allocation'" />
    <WorkspaceShell workspace="organization">
        <div class="space-y-6">
            <Link href="/organization/courses" class="inline-flex items-center gap-2 text-sm text-surface-500"><ArrowLeft class="h-4 w-4" /> Organization courses</Link>
            <header class="flex flex-wrap items-start justify-between gap-4"><div><p class="text-xs font-semibold uppercase tracking-widest text-primary-700">{{ organization.name }} · License #{{ license.id }}</p><h1 class="mt-2 max-w-3xl text-3xl font-display font-bold">{{ license.course?.title || 'Archived course' }}</h1><p class="mt-2 text-sm text-surface-500">{{ license.expires_at ? `License access through ${license.expires_at}` : 'No scheduled license expiry' }}</p></div><Button :disabled="!license.active || !license.course?.is_published" @click="form.clearErrors(); open = true"><UserPlus class="h-4 w-4" /> Assign learners</Button></header>
            <p v-if="!license.active || !license.course?.is_published" role="status" class="rounded-xl border border-amber-200 bg-amber-50 p-4 text-sm text-amber-900">This allocation is unavailable, expired, revoked or awaiting payment, or its course is unpublished. Contact your platform administrator. Existing learning records are preserved.</p>
            <div class="grid gap-4 sm:grid-cols-3"><div v-for="metric in [{ label: 'Total course places', value: license.quantity }, { label: 'Assigned places', value: license.used }, { label: 'Available to assign', value: license.available }]" :key="metric.label" class="rounded-2xl border border-surface-200 bg-white p-5"><p class="text-sm text-surface-500">{{ metric.label }}</p><p class="mt-2 text-3xl font-bold">{{ metric.value }}</p></div></div>
            <section class="overflow-hidden rounded-2xl border border-surface-200 bg-white"><div class="border-b border-surface-100 px-6 py-5"><h2 class="font-semibold">Assigned learners</h2><p class="mt-1 text-sm text-surface-500">Releasing a place stops access granted by this allocation. Progress and earned certificates stay on the learner’s record.</p></div>
                <div v-if="assignments.data.length" class="overflow-x-auto"><table class="w-full text-left text-sm"><caption class="sr-only">Assigned members and progress</caption><thead class="bg-surface-50 text-surface-500"><tr><th scope="col" class="px-6 py-3">Learner</th><th scope="col" class="px-4 py-3">Progress</th><th scope="col" class="px-4 py-3">Deadline</th><th scope="col" class="px-4 py-3">Action</th></tr></thead><tbody class="divide-y divide-surface-100"><tr v-for="assignment in assignments.data" :key="assignment.id"><td class="px-6 py-4"><p class="font-semibold">{{ assignment.member ? `${assignment.member.first_name} ${assignment.member.last_name}` : 'Former member' }}</p><p class="mt-1 text-xs text-surface-500">{{ assignment.member?.email }}</p><p v-if="assignment.member && !assignment.member.is_active" class="mt-1 text-xs text-amber-800">Account inactive</p></td><td class="px-4 py-4"><p class="font-semibold">{{ assignment.progress_pct || 0 }}%</p><p class="text-xs capitalize text-surface-500">{{ assignment.status }}</p></td><td class="whitespace-nowrap px-4 py-4 text-surface-500">{{ assignment.deadline || 'No deadline' }}</td><td class="px-4 py-4"><Button variant="ghost" size="sm" :aria-label="`Release place for ${assignment.member?.first_name || 'former member'}`" @click="removal.clearErrors(); releasing = assignment">Release place</Button></td></tr></tbody></table></div>
                <div v-else class="px-6 py-14 text-center"><Users class="mx-auto h-10 w-10 text-surface-300" /><h3 class="mt-4 font-semibold">Ready for your first learners</h3><p class="mt-2 text-sm text-surface-500">Assign selected members or a department to start their learning.</p></div>
            </section><SimplePagination :page="assignments" />
        </div>
        <Modal :show="open" title="Assign course places" :subtitle="license.course?.title" size="lg" :closeable="!form.processing" @close="open = false">
            <form @submit.prevent="assign" class="space-y-5"><fieldset class="flex flex-wrap gap-3"><legend class="mb-2 text-sm font-semibold">Who should take this course?</legend><label class="flex flex-1 items-center gap-2 rounded-xl border border-surface-200 p-3 text-sm"><input v-model="mode" type="radio" value="members" name="assignment-mode" /> Selected members</label><label class="flex flex-1 items-center gap-2 rounded-xl border border-surface-200 p-3 text-sm"><input v-model="mode" type="radio" value="department" name="assignment-mode" /> A department</label></fieldset>
                <template v-if="mode === 'members'"><div class="flex items-end gap-2"><Input v-model="query" label="Find active learners" placeholder="Name or email (at least 2 characters)" maxlength="100" class="min-w-0 flex-1" @keydown.enter.prevent="search" /><Button variant="secondary" :loading="searching" :disabled="query.trim().length < 2" @click="search"><Search class="h-4 w-4" /> Search</Button></div><p v-if="searchError" role="alert" class="text-sm text-red-700">{{ searchError }}</p><div class="max-h-48 space-y-2 overflow-y-auto"><label v-for="member in results" :key="member.id" class="flex items-center gap-3 rounded-xl border border-surface-200 p-3 text-sm"><input type="checkbox" :checked="selected.some(p => p.id === member.id)" @change="toggle(member)" /><span><strong>{{ member.first_name }} {{ member.last_name }}</strong><span class="block text-xs text-surface-500">{{ member.email }}</span></span></label></div><p v-if="searched && !results.length" role="status" class="text-sm text-surface-500">No active learners found. Invite members from People & invitations first.</p><div v-if="selected.length" class="rounded-xl bg-primary-50 p-3"><p class="text-sm font-semibold text-primary-900">{{ selected.length }} selected</p><div class="mt-2 flex flex-wrap gap-2"><button v-for="person in selected" :key="person.id" type="button" class="rounded-lg bg-white px-2 py-1 text-xs text-primary-800" :aria-label="`Remove ${person.first_name} ${person.last_name} from selection`" @click="toggle(person)">{{ person.first_name }} {{ person.last_name }} ×</button></div></div></template>
                <template v-else><label class="block text-sm font-semibold">Department<select v-model="form.department_id" required class="mt-2 block w-full rounded-xl border-surface-200"><option value="">Choose a department</option><option v-for="department in departments" :key="department.id" :value="department.id">{{ department.name }}</option></select></label><p class="text-sm leading-relaxed text-surface-500">All current active learners in this department are included. People who already have access are skipped. Future members are not added automatically. The entire request is kept unchanged if there are too few places or a member is ineligible.</p></template>
                <Input v-model="form.deadline" type="date" label="Completion deadline (optional)" :error="form.errors.deadline" />
                <p class="rounded-xl bg-surface-50 p-3 text-sm text-surface-600">{{ license.available }} places available. Existing progress and completion records are preserved.</p><p v-for="(error, key) in form.errors" :key="key" role="alert" class="text-sm text-red-700">{{ error }}</p>
                <div class="flex justify-end gap-3"><Button variant="secondary" :disabled="form.processing" @click="open = false">Cancel</Button><Button type="submit" :loading="form.processing" :disabled="mode === 'members' ? !selected.length : !form.department_id">Assign course</Button></div>
            </form>
        </Modal>
        <Modal :show="!!releasing" title="Release this course place?" :closeable="!removal.processing" @close="releasing = null"><p class="text-sm leading-relaxed text-surface-600">This place becomes available to another member. Access granted by this license stops immediately. The learner’s progress, completion records and earned certificates are kept.</p><p v-for="error in removal.errors" :key="error" role="alert" class="mt-3 text-sm text-red-700">{{ error }}</p><template #footer><Button variant="secondary" :disabled="removal.processing" @click="releasing = null">Keep assignment</Button><Button variant="danger" :loading="removal.processing" @click="release">Release place</Button></template></Modal>
    </WorkspaceShell>
</template>
